pub fn ledger(ops: List[Str]) -> Result[Map[Str, Int], Str] {
    var m: Map[Str, Int] = {}
    for op in ops {
        let w = words_of(op)
        let cmd = str_at(w, 0)
        let n = w.len()
        if cmd == "open" and n == 2 {
            let a = str_at(w, 1)
            if has(m, a) {
                return Err("exists " + a)
            }
            m = m.insert(a, 0)
        } else if cmd == "dep" and n == 3 {
            let a = str_at(w, 1)
            let amt = str_at(w, 2)
            if not all_digits(amt) {
                return Err("bad op")
            }
            if not has(m, a) {
                return Err("unknown " + a)
            }
            m = m.insert(a, bal(m, a) + num_of(amt))
        } else if cmd == "wd" and n == 3 {
            let a = str_at(w, 1)
            let amt = str_at(w, 2)
            if not all_digits(amt) {
                return Err("bad op")
            }
            if not has(m, a) {
                return Err("unknown " + a)
            }
            let k = num_of(amt)
            if bal(m, a) - k < 0 {
                return Err("insufficient " + a)
            }
            m = m.insert(a, bal(m, a) - k)
        } else if cmd == "move" and n == 4 {
            let a = str_at(w, 1)
            let b = str_at(w, 2)
            let amt = str_at(w, 3)
            if not all_digits(amt) {
                return Err("bad op")
            }
            if not has(m, a) {
                return Err("unknown " + a)
            }
            if not has(m, b) {
                return Err("unknown " + b)
            }
            let k = num_of(amt)
            if bal(m, a) - k < 0 {
                return Err("insufficient " + a)
            }
            m = m.insert(a, bal(m, a) - k)
            m = m.insert(b, bal(m, b) + k)
        } else {
            return Err("bad op")
        }
    }
    return Ok(m)
}

